import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { ref, push, set } from 'firebase/database';
import { db } from '../firebase';
import axios from 'axios';

function AddSeries() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [previewImage, setPreviewImage] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const fileInputRef = useRef(null);
  const [selectedShow, setSelectedShow] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    coverImage: '',
    totalSeasons: 1,
    seasonsData: {
      1: { episodeCount: 1 }
    },
    currentSeason: 1,
    currentEpisode: 1,
    watchingTogether: true,
    status: 'active',
    tmdbId: null
  });

  const TMDB_API_KEY = process.env.REACT_APP_TMDB_API_KEY;

  const searchShows = async (query) => {
    if (!query.trim()) {
      setSearchResults([]);
      return;
    }

    try {
      const response = await axios.get(`https://api.themoviedb.org/3/search/tv`, {
        params: {
          api_key: TMDB_API_KEY,
          query: query,
          language: 'tr-TR'
        }
      });

      setSearchResults(response.data.results);
    } catch (error) {
      console.error('Dizi arama hatası:', error);
      setError('Diziler aranırken bir hata oluştu');
    }
  };

  const getShowDetails = async (tmdbId) => {
    try {
      const response = await axios.get(`https://api.themoviedb.org/3/tv/${tmdbId}`, {
        params: {
          api_key: TMDB_API_KEY,
          language: 'tr-TR'
        }
      });

      const show = response.data;
      setFormData({
        ...formData,
        title: show.name,
        totalSeasons: show.number_of_seasons,
        coverImage: show.poster_path ? `https://image.tmdb.org/t/p/w500${show.poster_path}` : '',
        tmdbId: show.id,
        seasonsData: {}
      });

      // Sezon detaylarını al
      const seasonsData = {};
      for (let i = 1; i <= show.number_of_seasons; i++) {
        const seasonResponse = await axios.get(
          `https://api.themoviedb.org/3/tv/${tmdbId}/season/${i}`,
          {
            params: {
              api_key: TMDB_API_KEY,
              language: 'tr-TR'
            }
          }
        );
        seasonsData[i] = {
          episodes: seasonResponse.data.episodes.length
        };
      }

      setFormData(prev => ({
        ...prev,
        seasonsData
      }));

      setSelectedShow(show);
      setSearchResults([]);
    } catch (error) {
      console.error('Dizi detayları alınamadı:', error);
      setError('Dizi detayları alınırken bir hata oluştu');
    }
  };

  const handleSearchChange = (e) => {
    const query = e.target.value;
    setSearchQuery(query);
    if (query.length >= 3) {
      searchShows(query);
    } else {
      setSearchResults([]);
    }
  };

  const handleSelectShow = (show) => {
    getShowDetails(show.id);
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    
    if (name.startsWith('season_')) {
      const seasonNumber = parseInt(name.split('_')[1]);
      setFormData(prev => ({
        ...prev,
        seasonsData: {
          ...prev.seasonsData,
          [seasonNumber]: { episodeCount: parseInt(value) }
        }
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: type === 'checkbox' ? checked : type === 'number' ? Number(value) : value,
        // Sezon değiştiğinde mevcut bölümü sıfırla
        ...(name === 'currentSeason' && {
          currentEpisode: 1
        })
      }));
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        alert('Dosya boyutu 5MB\'dan küçük olmalıdır.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewImage(reader.result);
        setFormData(prev => ({
          ...prev,
          coverImage: reader.result
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const newSeriesRef = push(ref(db, 'series'));
      const seriesData = {
        ...formData,
        createdAt: new Date().toISOString(),
        watchedEpisodes: {
          beyza: {},
          mucahit: {}
        }
      };

      // Seçili sezon ve bölüme kadar olan tüm bölümleri izlendi olarak işaretle
      for (let season = 1; season <= formData.currentSeason; season++) {
        const episodeCount = formData.seasonsData[season]?.episodes || 0;
        const maxEpisode = season === formData.currentSeason ? formData.currentEpisode : episodeCount;
        
        for (let episode = 1; episode <= maxEpisode; episode++) {
          const episodeKey = `${season}-${episode}`;
          if (formData.watchingTogether) {
            seriesData.watchedEpisodes.beyza[episodeKey] = true;
            seriesData.watchedEpisodes.mucahit[episodeKey] = true;
          } else {
            seriesData.watchedEpisodes.beyza[episodeKey] = true;
          }
        }
      }

      await set(newSeriesRef, seriesData);
      navigate('/series');
    } catch (error) {
      console.error('Dizi eklenirken hata oluştu:', error);
      setError('Dizi eklenirken bir hata oluştu');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative">
      {/* Yarı saydam arka plan */}
      <div 
        className="fixed inset-0 opacity-20"
        style={{
          backgroundImage: `url(/images/background.jpg)`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
          width: '100vw',
          height: '100vh',
          zIndex: -1
        }}
      />
      
      {/* Gradient overlay */}
      <div 
        className="fixed inset-0 bg-gradient-to-br from-purple-50/90 to-pink-50/90"
        style={{ 
          zIndex: -1,
          width: '100vw',
          height: '100vh'
        }}
      />

      {/* Ana içerik */}
      <div className="relative py-8 px-4 min-h-screen">
        <div className="max-w-2xl mx-auto">
          <div className="bg-white/90 backdrop-blur-sm rounded-xl shadow-lg overflow-hidden">
            <div className="bg-gradient-to-r from-purple-600 to-pink-600 p-6">
              <h1 className="text-2xl font-bold text-white flex items-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-2" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" />
                </svg>
                Yeni Dizi Ekle
              </h1>
            </div>

            <div className="p-6">
              {/* Arama Bölümü */}
              <div className="mb-6">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Dizi Ara
                </label>
                <div className="flex space-x-2">
                  <input
                    type="text"
                    value={searchQuery}
                    onChange={handleSearchChange}
                    placeholder="Dizi adını girin..."
                    className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                  />
                  <button
                    onClick={() => searchShows(searchQuery)}
                    disabled={isSearching}
                    className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition duration-200 flex items-center"
                  >
                    {isSearching ? (
                      <>
                        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Aranıyor...
                      </>
                    ) : (
                      <>
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" />
                        </svg>
                        Ara
                      </>
                    )}
                  </button>
                </div>

                {/* Arama Sonuçları */}
                {searchResults.length > 0 && (
                  <div className="mt-4 space-y-2">
                    {searchResults.map((series) => (
                      <div
                        key={series.id}
                        onClick={() => handleSelectShow(series)}
                        className="flex items-center space-x-3 p-3 bg-gray-50 rounded-lg cursor-pointer hover:bg-gray-100 transition duration-200"
                      >
                        {series.poster_path ? (
                          <img
                            src={`https://image.tmdb.org/t/p/w92${series.poster_path}`}
                            alt={series.name}
                            className="w-12 h-18 object-cover rounded"
                          />
                        ) : (
                          <div className="w-12 h-18 bg-gray-200 rounded flex items-center justify-center">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" viewBox="0 0 20 20" fill="currentColor">
                              <path fillRule="evenodd" d="M4 3a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V5a2 2 0 00-2-2H4zm12 12H4l4-8 3 6 2-4 3 6z" clipRule="evenodd" />
                            </svg>
                          </div>
                        )}
                        <div>
                          <h3 className="font-medium text-gray-900">{series.name}</h3>
                          <p className="text-sm text-gray-500">
                            {series.first_air_date?.split('-')[0] || 'Yıl bilgisi yok'}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {selectedShow && (
                <div className="p-4 bg-purple-50 rounded-lg">
                  <div className="flex items-center space-x-4">
                    {selectedShow.poster_path && (
                      <img
                        src={`https://image.tmdb.org/t/p/w154${selectedShow.poster_path}`}
                        alt={selectedShow.name}
                        className="w-20 h-28 object-cover rounded"
                      />
                    )}
                    <div>
                      <h3 className="font-medium text-lg">{selectedShow.name}</h3>
                      <p className="text-sm text-gray-600">
                        {selectedShow.first_air_date ? new Date(selectedShow.first_air_date).getFullYear() : 'Tarih yok'}
                        {selectedShow.number_of_seasons && ` • ${selectedShow.number_of_seasons} Sezon`}
                      </p>
                      <p className="text-sm text-gray-600 mt-1">{selectedShow.overview}</p>
                    </div>
                  </div>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-6">
                <div>
                  <label htmlFor="title" className="block text-sm font-medium text-gray-700 mb-1">
                    Dizi Adı
                  </label>
                  <input
                    type="text"
                    id="title"
                    name="title"
                    value={formData.title}
                    onChange={handleChange}
                    required
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition duration-200"
                    placeholder="Dizi adını girin"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Kapak Resmi
                  </label>
                  <div
                    onClick={() => fileInputRef.current.click()}
                    className={`border-2 border-dashed rounded-lg p-4 text-center cursor-pointer transition duration-200 ${
                      previewImage
                        ? 'border-purple-500 bg-purple-50'
                        : 'border-gray-300 hover:border-purple-500 hover:bg-purple-50'
                    }`}
                  >
                    <input
                      type="file"
                      ref={fileInputRef}
                      onChange={handleImageChange}
                      accept="image/*"
                      className="hidden"
                    />
                    {previewImage ? (
                      <div className="relative">
                        <img
                          src={previewImage}
                          alt="Preview"
                          className="max-h-48 mx-auto rounded-lg"
                        />
                        <div className="absolute inset-0 bg-black/50 opacity-0 hover:opacity-100 transition duration-200 rounded-lg flex items-center justify-center">
                          <p className="text-white text-sm">Resmi değiştirmek için tıklayın</p>
                        </div>
                      </div>
                    ) : (
                      <div className="py-8">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto text-gray-400 mb-2" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M4 3a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V5a2 2 0 00-2-2H4zm12 12H4l4-8 3 6 2-4 3 6z" clipRule="evenodd" />
                        </svg>
                        <p className="text-sm text-gray-600">
                          Kapak resmi eklemek için tıklayın veya sürükleyin
                        </p>
                      </div>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-1 gap-4">
                  <div>
                    <label htmlFor="totalSeasons" className="block text-sm font-medium text-gray-700 mb-1">
                      Toplam Sezon
                    </label>
                    <input
                      type="number"
                      id="totalSeasons"
                      name="totalSeasons"
                      value={formData.totalSeasons}
                      onChange={(e) => {
                        const newTotalSeasons = parseInt(e.target.value);
                        setFormData(prev => {
                          const newSeasonsData = { ...prev.seasonsData };
                          // Yeni sezonlar ekle
                          for (let i = 1; i <= newTotalSeasons; i++) {
                            if (!newSeasonsData[i]) {
                              newSeasonsData[i] = { episodeCount: 1 };
                            }
                          }
                          // Fazla sezonları sil
                          Object.keys(newSeasonsData).forEach(season => {
                            if (parseInt(season) > newTotalSeasons) {
                              delete newSeasonsData[season];
                            }
                          });
                          return {
                            ...prev,
                            totalSeasons: newTotalSeasons,
                            seasonsData: newSeasonsData,
                            currentSeason: Math.min(prev.currentSeason, newTotalSeasons)
                          };
                        });
                      }}
                      min="1"
                      required
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition duration-200"
                    />
                  </div>

                  {/* Her sezon için bölüm sayısı girişi */}
                  <div className="space-y-4">
                    <label className="block text-sm font-medium text-gray-700">
                      Sezon Başına Bölüm Sayıları
                    </label>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                      {Array.from({ length: formData.totalSeasons }, (_, i) => i + 1).map((season) => (
                        <div key={season}>
                          <label htmlFor={`season_${season}`} className="block text-sm text-gray-600 mb-1">
                            Sezon {season}
                          </label>
                          <input
                            type="number"
                            id={`season_${season}`}
                            name={`season_${season}`}
                            value={formData.seasonsData[season]?.episodeCount || 1}
                            onChange={handleChange}
                            min="1"
                            required
                            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition duration-200"
                          />
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label htmlFor="currentSeason" className="block text-sm font-medium text-gray-700 mb-1">
                        Mevcut Sezon
                      </label>
                      <input
                        type="number"
                        id="currentSeason"
                        name="currentSeason"
                        value={formData.currentSeason}
                        onChange={handleChange}
                        min="1"
                        max={formData.totalSeasons}
                        required
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition duration-200"
                      />
                    </div>

                    <div>
                      <label htmlFor="currentEpisode" className="block text-sm font-medium text-gray-700 mb-1">
                        Mevcut Bölüm
                      </label>
                      <input
                        type="number"
                        id="currentEpisode"
                        name="currentEpisode"
                        value={formData.currentEpisode}
                        onChange={handleChange}
                        min="1"
                        max={formData.seasonsData[formData.currentSeason]?.episodeCount || 1}
                        required
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition duration-200"
                      />
                    </div>
                  </div>
                </div>

                <div className="flex items-center">
                  <input
                    type="checkbox"
                    id="watchingTogether"
                    name="watchingTogether"
                    checked={formData.watchingTogether}
                    onChange={handleChange}
                    className="h-4 w-4 text-purple-600 focus:ring-purple-500 border-gray-300 rounded transition duration-200"
                  />
                  <label htmlFor="watchingTogether" className="ml-2 block text-sm text-gray-700">
                    Birlikte İzliyoruz
                  </label>
                </div>

                <div className="flex justify-end space-x-4">
                  <button
                    type="button"
                    onClick={() => navigate('/series')}
                    className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition duration-200"
                  >
                    İptal
                  </button>
                  <button
                    type="submit"
                    disabled={loading || !selectedShow}
                    className="px-4 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 transition duration-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
                  >
                    {loading ? (
                      <>
                        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Ekleniyor...
                      </>
                    ) : (
                      <>
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                        </svg>
                        Dizi Ekle
                      </>
                    )}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default AddSeries;
